import React from 'react';

function sanitizeSvgContent(content) {
  if (!React.isValidElement(content)) {
    return content;
  }

  const nextChildren = React.Children.map(content.props.children, (child) => {
    if (!React.isValidElement(child)) {
      return child;
    }

    if (child.type === 'path' && !child.props?.d) {
      return null;
    }

    return sanitizeSvgContent(child);
  });

  if (content.type === 'path' && !content.props?.d) {
    return null;
  }

  return React.cloneElement(content, undefined, nextChildren);
}

