export function NavIcon({ name, className = '' }) {
  const iconData = icons[name];

  if (!iconData) {
    return null;
  }

  // Check if it's the new object format (with explicit viewBox) or the old simple React Node
  const isObject = iconData && typeof iconData === 'object' && 'viewBox' in iconData;

  // Default to 400x400 if it's a simple path, otherwise use the specific viewBox
  const viewBox = isObject ? iconData.viewBox : '0 0 400 400';
  const content = sanitizeSvgContent(isObject ? iconData.content : iconData);

  if (!content) {
    return null;
  }

  return (
    <svg
      className={className}
      viewBox={viewBox}
      xmlns="http://www.w3.org/2000/svg"
      fill="currentColor"
    >
      <g>{content}</g>
    </svg>
  );
}
